  for ref,parts in anchors.items():
   for part in parts:self.assertIn(part,cases[ref.replace(':','-')]['analysis'])
  self.assertIn('be:pr and be:pa and be:fu',cases['16-5']['analysis'])
  self.assertIn('ipl as thief come:pr',cases['16-15']['analysis'])
  self.assertIn('i to thee great whore',cases['17-1']['analysis'])
  self.assertIn('and yet be:pr',cases['17-8']['analysis'])
  self.assertIn('mypl/people out of she',cases['18-4']['analysis'])
  self.assertIn('ipl queen sit:pr and no widow be:pr and no sorrow see:fu',cases['18-7']['analysis'])
  self.assertIn('slave:pl and man:pl kjv_soul:pl',cases['18-13']['analysis'])
  self.assertIn('all in ship:pl company',cases['18-17']['analysis'])
  self.assertIn('you holy kjv_apostle:pl and prophet:pl',cases['18-20']['analysis'])
  self.assertEqual(len(set(lang.lexicon)-set(prior.lexicon)),7)
  self.assertEqual(manifest['baseForgeHead'],read(prior.folder/'manifest.json')['forgeHead'])
